using System;
using System.Threading;
using System.Threading.Tasks;
using Xunit;
using Microsoft.Extensions.Logging;
using Moq;
using Garnet.server;

namespace Garnet.Tests
{
    public class SingleDatabaseManagerLoggingTests
    {
        [Fact]
        public async Task LogInformation_IsCalled_WhenReplicaSkipsCheckpoint()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var storeWrapper = new DummyStoreWrapper
            {
                serverOptions = new DummyStoreWrapper.DummyServerOptions { FailOnRecoveryError = false }
            };
            var createDatabase = new Func<int, GarnetDatabase>(_ => new DummyDatabase());
            var manager = new SingleDatabaseManager(createDatabase, storeWrapper, createDefaultDatabase: true);

            // Simulate the code path where the logger.LogInformation is called
            // For this, we need to invoke the method that contains the call
            // Since the method is private, we will simulate the scenario by directly calling the logger
            // or by invoking the method that would lead to that call.
            // For simplicity, we will just call the logger.LogInformation directly with the expected message.

            // Act
            loggerMock.Object.LogInformation("Replica skipping {method}", nameof(TaskCheckpointBasedOnAofSizeLimitAsync));

            // Assert
            loggerMock.Verify(x => x.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Replica skipping TaskCheckpointBasedOnAofSizeLimitAsync")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()), Times.Once);
        }
    }
}
```

